     /*insertMasterMdCtReportSalesTotal*/
	INSERT INTO KEP_REPORT_TOTAL					
	(
		TOTAL_MONTH
		, GROUP_CODE
		, GROUP_NAME
		, CREATE_FLAG
		, BUYER
		, DEPARTMENT
		, RESULT_AMT
		, ADD_DATE
	) VALUES (									
		#{st_close_month}
		,#{st_group_code}
		,#{st_group_nm}
		,'M'
		,#{COM_CODE}
		,#{DEPT_CODE}
		,#{AR_AMT}
		,SYSDATE
	)


		     /*deleteMasterMdCtReportSalesTotal*/
             DELETE  KEP_REPORT_TOTAL
				WHERE TOTAL_MONTH = #{st_close_month} 
				AND GROUP_CODE = #{st_group_code}
				AND CREATE_FLAG ='M'


		     /*updateMasterMdCtReportSalesDt*/
             UPDATE  KEP_REPORT_DT
             SET




					   TR_STATUS = 'Y'  




						TRDT_STATUS = 'Y'   




             , CHANGE_DATE= SYSDATE
             , CHANGE_USER_ID = #{st_user_id}
             WHERE REPORT_NO = #{st_report_no}


