     /*insertMasterMdCtReportSalesNewPop*/
	INSERT INTO KEP_REPORT_TOTAL_NEW					
	(
		TOTAL_MONTH
		, GROUP_CODE
		, GROUP_NAME
		, CREATE_FLAG
		, TYPE
		, TOTAL_CNT
		, TOTAL_AMT
		, BUYER_INFO
		, ADD_DATE
	) VALUES (									
		#{st_close_month}
		,#{st_group_code}
		,#{st_group_nm}
		,'M'
		,#{TYPE}
		,#{TOTAL_CNT}
		,#{TOTAL_AMT}
		,KEP.GET_BUYER_KEP_REPORT(#{st_group_code})
		,SYSDATE
	)


    /*updateMasterMdCtReportSalesNewPop*/
	UPDATE KEP_REPORT_TOTAL_NEW
	SET TOTAL_CNT = #{TOTAL_CNT}
	, TOTAL_AMT = #{TOTAL_AMT}	
	, BUYER_INFO = KEP.GET_BUYER_KEP_REPORT(#{st_group_code})
	, ADD_DATE = SYSDATE
	WHERE  TOTAL_MONTH = #{st_close_month}
	AND GROUP_CODE = #{st_group_code}	
	AND TYPE = #{TYPE}		
	AND CREATE_FLAG = 'M'


