     /*insertMasterMdCtReportSalesSgPop*/
	INSERT INTO KEP_REPORT_TOTAL_SG					
	(
		TOTAL_MONTH
		, GROUP_CODE
		, GROUP_NAME
		, CREATE_FLAG
		, SG_ID
		, SG_NAME
		, ITEM_CNT
		, B_TOTLA_AMT
		, P_MONTH_AMT
		, RD_AMT
		, BUYER_INFO
		, ADD_DATE
	) VALUES (									
		#{st_close_month}
		,#{st_group_code}
		,#{st_group_nm}
		,'M'
		,UPPER(#{SG_ID})
		,(SELECT MG.SG_NAME FROM KEPSGMG MG
			WHERE MG.SG_ID =#{SG_ID})
		,#{ITEM_CNT}
		,#{B_TOTLA_AMT}
		,#{P_MONTH_AMT}
		,#{B_TOTLA_AMT}-#{P_MONTH_AMT}
		,KEP.GET_BUYER_KEP_REPORT(#{st_group_code})
		,SYSDATE
	)


    /*updateMasterMdCtReportSalesSgPop*/
	UPDATE KEP_REPORT_TOTAL_SG
	SET B_TOTLA_AMT = #{B_TOTLA_AMT}
	, P_MONTH_AMT = #{P_MONTH_AMT}	
	, RD_AMT = #{B_TOTLA_AMT}-#{P_MONTH_AMT}
	, ITEM_CNT = #{ITEM_CNT}
	, BUYER_INFO = KEP.GET_BUYER_KEP_REPORT(#{st_group_code})
	, SG_NAME = (SELECT MG.SG_NAME FROM KEPSGMG MG
					WHERE MG.SG_ID =#{SG_ID})
	, ADD_DATE = SYSDATE
	WHERE  TOTAL_MONTH = #{st_close_month}
	AND GROUP_CODE = #{st_group_code}	
	AND SG_ID = #{SG_ID}		
	AND CREATE_FLAG = 'M'


    /*deleteMasterMdCtReportSalesSgPop*/
	DELETE KEP_REPORT_TOTAL_SG
	WHERE  TOTAL_MONTH = #{st_close_month}
	AND GROUP_CODE = #{st_group_code}	
	AND SG_ID = #{SG_ID}		
	AND CREATE_FLAG = 'M'


