     /*insertMasterMdCtReportSalesCaPop*/
	INSERT INTO KEP_REPORT_CA					
	(
		TOTAL_MONTH
		, GROUP_CODE
		, GROUP_NAME
		, CREATE_FLAG
		, BUYER
		, CATEGORY
		, CATEGORY_NAME
		, ITEM_CMT
		, B_TOTLA_AMT
		, P_MONTH_AMT
		, RD_AMT
		, BUYER_INFO
		, ADD_DATE
	) VALUES (									
		#{st_close_month}
		,#{st_group_code}
		,#{st_group_nm}
		,'M'
		,#{BUYER}
		,(SELECT BYCA.STD_CATEG_ID FROM ICOMBYCA BYCA
			WHERE COM_CODE = #{BUYER}
			AND STD_CATEG_ID = #{CATEGORY}
			AND DEPTH ='1'
			AND STATUS != 'D')
		,(SELECT BYCA.CATEG_NAME FROM ICOMBYCA BYCA
			WHERE COM_CODE = #{BUYER}
			AND STD_CATEG_ID = #{CATEGORY}
			AND DEPTH ='1'
			AND STATUS != 'D')
		,#{ITEM_CNT}
		,#{B_TOTLA_AMT}
		,#{P_MONTH_AMT}
		,#{B_TOTLA_AMT}-#{P_MONTH_AMT}
		,KEP.GET_BUYER_KEP_REPORT(#{st_group_code})
		,SYSDATE
	)


    /*updateMasterMdCtReportSalesCaPop*/
	UPDATE KEP_REPORT_CA
	SET B_TOTLA_AMT = #{B_TOTLA_AMT}
	, P_MONTH_AMT = #{P_MONTH_AMT}	
	, RD_AMT = #{B_TOTLA_AMT}-#{P_MONTH_AMT}
	, ITEM_CMT = #{ITEM_CNT}
	, BUYER_INFO = KEP.GET_BUYER_KEP_REPORT(#{st_group_code})
	, CATEGORY_NAME = (SELECT BYCA.CATEG_NAME FROM ICOMBYCA BYCA
						WHERE COM_CODE = #{BUYER}
						AND STD_CATEG_ID = #{CATEGORY}
						AND DEPTH ='1'
						AND STATUS != 'D')
	, ADD_DATE = SYSDATE
	WHERE  TOTAL_MONTH = #{st_close_month}
	AND GROUP_CODE = #{st_group_code}
	AND BUYER = #{BUYER}		
	AND CATEGORY = #{CATEGORY}		
	AND CREATE_FLAG = 'M'


    /*deleteMasterMdCtReportSalesCaPop*/
